insert into public.waypoint_catalog(id,data) values(9,'{"id":9,"createdAt":"2026-10-08T04:17:59.201Z","company":"Supabase","title":"Executive Assistant to the CEO","headquarters":"Unknown","employmentType":"Full-time","workArrangement":"100% Remote","originalSalary":"","monthlySalaryPhp":null,"philippinesEligibility":"Unknown","directEmployerStatus":"Unknown","employerCategory":"Direct company","applicationStatus":"Discovered","applicationLink":"https://jobs.ashbyhq.com/supabase/b566fbf8-2894-4314-9533-8fa920e80c19/application","evidence":"Official employer discovery; checked 2026-10-08 (Australia/Sydney). APAC timezone is compatible with the Philippines, but country-specific employment eligibility and headquarters need verification. Salary missing. Original vacancy: https://jobs.ashbyhq.com/supabase/b566fbf8-2894-4314-9533-8fa920e80c19. Source: official Ashby public job feed. Published 2026-10-06T14:33:50.071+00:00. No AI match score or automation permission is asserted. Confirm original terms before applying.\nAPPLICANT FIT REVIEW (2026-10-08): Focus for manual review: operations, coordination, customer service, account relationships or executive support. Confirm role-specific qualifications, salary and international direct-employer evidence. No developer expertise is claimed.","isDemo":false,"jobDescription":"RESEARCH SUMMARY — not the full original job description. Checked 2026-10-08 (Australia/Sydney).\nFull-time executive support role in an APJ/APAC timezone. Fully remote. Responsibilities cover CEO calendar, inbox, briefings, travel, confidential information and follow-through. Executive support in a startup or scale-up and remote teamwork are requested. Employer says it hires globally. Salary is not published.","employerSources":[]}'::jsonb) on conflict(id) do nothing;
