insert into public.waypoint_catalog(id,data) values(14,'{"id":14,"createdAt":"2026-10-08T04:17:59.345Z","company":"Celigo","title":"Account Manager","headquarters":"Unknown","employmentType":"Unknown","workArrangement":"Unknown","originalSalary":"","monthlySalaryPhp":null,"philippinesEligibility":"Yes","directEmployerStatus":"Unknown","employerCategory":"Direct company","applicationStatus":"Discovered","applicationLink":"https://job-boards.greenhouse.io/celigo/jobs/8211343","evidence":"Official employer discovery; checked 2026-10-08 (Australia/Sydney). Philippines location confirmed. Fully remote arrangement, employment type, headquarters and salary need confirmation. Required LinkedIn profile and US-hours availability are not saved answers. Original job page: https://job-boards.greenhouse.io/celigo/jobs/8211343. No AI match score or automation permission is asserted. Confirm original terms before applying.\nAPPLICANT FIT REVIEW (2026-10-08): Focus for manual review: operations, coordination, customer service, account relationships or executive support. Confirm role-specific qualifications, salary and international direct-employer evidence. No developer expertise is claimed.","isDemo":false,"jobDescription":"RESEARCH SUMMARY — not the full original job description. Checked 2026-10-08 (Australia/Sydney).\nAccount management role based in the Philippines. Build customer relationships, drive account growth, upselling and renewals. Requests 3–5 years in account management, sales or a related field, preferably technology/SaaS; strong Salesforce skills and a sales track record. US business hours Monday–Friday. Company describes a remote-first culture. Salary and full employment terms are not published.","employerSources":[]}'::jsonb) on conflict(id) do nothing;
