-- CASA RUSTIA WAYPOINT â€” COMPLETE SUPABASE DATABASE SETUP
-- Run this entire file in your project's SQL editor using its administrator connection.
-- Creates Waypoint tables/functions, per-user access policies, a private resume bucket,
-- and the 233 saved public catalog jobs. No API keys, resumes or account passwords.
-- Existing workspace data is preserved. Existing catalog IDs are not overwritten.
-- Authentication redirect settings and frontend/Edge Function deployment are separate.
begin;
grant usage on schema public to authenticated;
-- Run once in the SQL editor of your own Supabase project.
-- Adds Waypoint tables only. Existing application tables and local SQLite data are untouched.

create table if not exists public.waypoint_catalog (
 id bigint primary key,
 data jsonb not null check (jsonb_typeof(data)='object')
);
create table if not exists public.waypoint_workspaces (
 user_id uuid primary key references auth.users(id) on delete cascade,
 data jsonb not null check (jsonb_typeof(data)='object'),
 revision bigint not null default 0,
 updated_at timestamptz not null default now()
);
alter table public.waypoint_catalog enable row level security;
alter table public.waypoint_workspaces enable row level security;
revoke all on public.waypoint_catalog, public.waypoint_workspaces from anon, authenticated;
grant select on public.waypoint_catalog, public.waypoint_workspaces to authenticated;
drop policy if exists waypoint_catalog_read on public.waypoint_catalog;
create policy waypoint_catalog_read on public.waypoint_catalog for select to authenticated using (true);
drop policy if exists waypoint_workspace_read on public.waypoint_workspaces;
create policy waypoint_workspace_read on public.waypoint_workspaces for select to authenticated using ((select auth.uid())=user_id);

create or replace function public.waypoint_load_workspace(p_defaults jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid := auth.uid(); result public.waypoint_workspaces; listings jsonb; next_id bigint;
begin
 if uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if jsonb_typeof(p_defaults) is distinct from 'object' then raise exception 'Invalid defaults'; end if;
 select coalesce(jsonb_agg(data order by id),'[]'::jsonb),coalesce(max(id),0)+1 into listings,next_id from public.waypoint_catalog;
 select * into result from public.waypoint_workspaces where user_id=uid;
 return jsonb_build_object('data',result.data,'revision',result.revision);
end $$;
create or replace function public.waypoint_save_workspace(p_revision bigint,p_data jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); result public.waypoint_workspaces;
begin
 if uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if jsonb_typeof(p_data) is distinct from 'object' or jsonb_typeof(p_data->'jobs') is distinct from 'array' or jsonb_typeof(p_data->'settings') is distinct from 'object' or jsonb_typeof(p_data->'profile') is distinct from 'object' or octet_length(p_data::text)>16777216 then raise exception 'Invalid workspace'; end if;
 if jsonb_array_length(p_data->'jobs')>10000 then raise exception 'Workspace job limit reached'; end if;
 update public.waypoint_workspaces set data=p_data,revision=revision+1,updated_at=now() where user_id=uid and revision=p_revision returning * into result;
 if not found then raise exception 'Workspace changed; reload before saving' using errcode='40001'; end if;
 return jsonb_build_object('data',result.data,'revision',result.revision);
end $$;
revoke all on function public.waypoint_load_workspace(jsonb),public.waypoint_save_workspace(bigint,jsonb) from public,anon;
grant execute on function public.waypoint_load_workspace(jsonb),public.waypoint_save_workspace(bigint,jsonb) to authenticated;
grant all on public.waypoint_catalog, public.waypoint_workspaces to service_role;

values('waypoint-resumes','waypoint-resumes',false,3145728,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain'])
on conflict(id) do update set public=false,file_size_limit=3145728,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists waypoint_resume_read on storage.objects;
drop policy if exists waypoint_resume_insert on storage.objects;
drop policy if exists waypoint_resume_delete on storage.objects;
create policy waypoint_resume_read on storage.objects for select to authenticated using(bucket_id='waypoint-resumes' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy waypoint_resume_insert on storage.objects for insert to authenticated with check(bucket_id='waypoint-resumes' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy waypoint_resume_delete on storage.objects for delete to authenticated using(bucket_id='waypoint-resumes' and (storage.foldername(name))[1]=(select auth.uid())::text);

-- Public employer listings only. No profiles, passwords, contacts, resumes or application history.


notify pgrst, 'reload schema';
commit;

-- Setup summary: on a fresh installation, catalog_jobs should be 233.
-- All readiness booleans should be true.
select
 (select count(*) from public.waypoint_catalog) as catalog_jobs,
 (select not public from storage.buckets where id='waypoint-resumes') as resume_bucket_private,
 to_regprocedure('public.waypoint_load_workspace(jsonb)') is not null as load_function_ready,
 to_regprocedure('public.waypoint_save_workspace(bigint,jsonb)') is not null as save_function_ready,
 (select relrowsecurity from pg_class where oid='public.waypoint_workspaces'::regclass) as workspace_rls_enabled;
